def solve24(nums):
    if len(nums) == 1:
        return abs(nums[0] - 24) < 1e-6
    for i in range(len(nums)):
        for j in range(len(nums)):
            if i == j: continue
            rest = [nums[k] for k in range(len(nums)) if k!=i and k!=j]
            a, b = nums[i], nums[j]
            for val in [a+b, a-b, a*b] + ([a/b] if b else []):
                if solve24(rest + [val]):
                    return True
    return False
